function buildSecurityHeaders() {
    return `// src/middleware/security-headers.ts — generated by oweibo module-compliance
import type { Request, Response, NextFunction } from 'express';

/**
 * Apply security headers beyond what helmet provides by default.
 * PCI-DSS §6.5.10 and OWASP ASVS L2 require explicit CSP + HSTS.
 */
export function securityHeaders(req: Request, res: Response, next: NextFunction): void {
  // Content Security Policy
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; connect-src 'self'; frame-ancestors 'none'",
  );

  // HTTP Strict Transport Security (1 year, includeSubDomains)
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains; preload');

  // Prevent MIME sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Disable embedding in iframes
  res.setHeader('X-Frame-Options', 'DENY');

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Permissions policy
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');

  // Remove fingerprinting header
  res.removeHeader('X-Powered-By');

  next();
}
`;
}
function buildRateLimiter() {
    return `// src/middleware/rate-limiter.ts — generated by oweibo module-compliance
import type { Request, Response, NextFunction } from 'express';

interface RateLimiterOptions {
  windowMs: number;
  maxRequests: number;
  keyFn?: (req: Request) => string;
  message?: string;
}

interface BucketEntry { count: number; resetAt: number; }

/**
 * In-process sliding-window rate limiter (single instance).
 * For multi-process deployments, replace with Redis-backed express-rate-limit.
 */
export function createRateLimiter(options: RateLimiterOptions) {
  const { windowMs, maxRequests, keyFn, message } = options;
  const buckets = new Map<string, BucketEntry>();

  // Cleanup stale buckets every window
  const cleanup = setInterval(() => {
    const now = Date.now();
    for (const [key, entry] of buckets.entries()) {
      if (entry.resetAt < now) buckets.delete(key);
    }
  }, windowMs);
  if (cleanup.unref) cleanup.unref();

  return function rateLimiter(req: Request, res: Response, next: NextFunction): void {
    const key = keyFn ? keyFn(req) : (req.ip ?? 'unknown');
    const now = Date.now();
    const entry = buckets.get(key);

    if (!entry || entry.resetAt < now) {
      buckets.set(key, { count: 1, resetAt: now + windowMs });
      next();
      return;
    }

    if (entry.count >= maxRequests) {
      const retryAfter = Math.ceil((entry.resetAt - now) / 1000);
      res.setHeader('Retry-After', String(retryAfter));
      res.status(429).json({ error: 'too_many_requests', message: message ?? 'Rate limit exceeded', retryAfterSeconds: retryAfter });
      return;
    }

    entry.count++;
    next();
  };
}

/** Standard API rate limiter: 100 req/min per IP. */
export const apiRateLimiter = createRateLimiter({ windowMs: 60_000, maxRequests: 100 });

/** Auth endpoint rate limiter: 10 req/min per IP (brute-force protection). */
export const authRateLimiter = createRateLimiter({ windowMs: 60_000, maxRequests: 10, message: 'Too many auth attempts, please wait' });
`;
}
